mapper.select:
select userCode, userId, userPwd, userImg, userNickname, userName, userCreate, userUpdate, userDelete, userManager, userYn, userStopYn, userStopDate, LEAST( 100, userTotalPointer + ( SELECT IFNULL(SUM(userPointer), 0) FROM JGUserInfoPointer WHERE userCode = JGUserInfo.userCode ) ) AS userTotalPointer, addressData, addressDetailData, userAddressDetail, userInfo from JGUserInfo
AND userId LIKE CONCAT('%', #{userId}, '%')
AND userManager = #{userManager}
AND userManager = #{userManager}
AND userStopDate is null AND userDelete is null
AND userStopDate is not null
AND userDelete is not null
limit #{cri.skip} ,#{cri.amount};

mapper.update:
update JGUserInfo
set userManager = #{userManager}
where userCode = #{userCode};

update JGUserInfo
set userDelete = now()
where userCode = #{int};

update JGUserInfo
set userDelete = null
where userCode = #{int};

update JGUserInfo
set userStopDate = now()
where userCode = #{int};

update JGUserInfo
set userStopDate = null
where userCode = #{int};

update UserDeclarationA
set userDeclarationBoo = #{userDeclarationBoo} ,
    userDeclarationTextComment = #{textState} ,
    userDeclarationStateBoo = #{checkBooText},
    userDeclarationProcessUser = #{userCode}
where userDeclarationCode = #{declarationCode};

UPDATE JGUserInfo
SET userStopDate = TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL #{selectOption} DAY)),  userStopYn = true
WHERE userCode = #{userCode};

Update notificationManagement
set notificationManagementImg = #{fileName}
where notificationManagementCode = #{code};

Update notificationManagement
set notificationManagementTitle = #{notificationManagementTitle} , notificationManagementText = #{notificationManagementText}
where notificationManagementCode = #{notificationManagementCode};

mapper.delete:
Update notificationManagement
set notificationManagementBoo = false
where notificationManagementCode = #{code};

mapper.update:
update categoryStateMajor
set categoryStateMajorText = #{categoryStateMajorText}
where categoryStateMajorCode = #{categoryStateMajorCode};

mapper.select:
select categoryStateMinorCode,categoryStateMinorText
from categoryStateMinor
where categoryStateMinorCodeMinor = ${code}

mapper.update:
UPDATE categoryStateMinor
set categoryStateMinorCodeMinor = #{categoryStateMinorCodeMinor}
where categoryStateMinorCode = #{categoryStateMinorCode}
